// @generated by:gauntlet run:godseye-local-jobs
import { randomUUID } from "node:crypto";
import { afterEach, beforeEach, describe, expect, it } from "vitest";
import { nextCronFire, parseCron } from "../packages/core/src/jobs-cron.js";
import { type JobsFixture, jobsFixture } from "./jobs-helpers.js";

describe("cron schedule computation", () => {
  const at = (text: string) => new Date(text);
  it("computes the next UTC fire strictly after the reference", () => {
    expect(nextCronFire("*/15 * * * *", at("2026-11-11T12:00:00.000Z"))?.toISOString()).toBe(
      "2026-11-11T12:15:00.000Z",
    );
    expect(nextCronFire("30 2 * * *", at("2026-11-11T12:00:00.000Z"))?.toISOString()).toBe(
      "2026-11-12T02:30:00.000Z",
    );
    expect(nextCronFire("0 0 1 1 *", at("2026-11-11T12:00:00.000Z"))?.toISOString()).toBe(
      "2027-01-01T00:00:00.000Z",
    );
    expect(nextCronFire("0 9 * * 1-5", at("2026-11-13T10:00:00.000Z"))?.toISOString()).toBe(
      "2026-11-16T09:00:00.000Z",
    );
    expect(nextCronFire("5,10 1 * * *", at("2026-11-11T01:05:00.000Z"))?.toISOString()).toBe(
      "2026-11-11T01:10:00.000Z",
    );
  });
  it("rejects malformed or out-of-range expressions and unsatisfiable dates", () => {
    for (const bad of [
      "* * * *",
      "60 * * * *",
      "* 24 * * *",
      "*/0 * * * *",
      "a b c d e",
      "5-1 * * * *",
    ])
      expect(() => parseCron(bad)).toThrow();
    expect(nextCronFire("0 0 31 2 *", at("2026-01-01T00:00:00.000Z"))).toBeNull();
  });
});

describe("durable job registry and runs", () => {
  let fixture: JobsFixture;
  beforeEach(async () => {
    fixture = await jobsFixture();
  });
  afterEach(async () => {
    await fixture.store.close();
  });

  it("registers per cell with revision, hash and idempotency protection", async () => {
    const key = randomUUID();
    const first = await fixture.register({}, key);
    expect(first.revision).toBe(0);
    expect(await fixture.register({}, key)).toEqual(first);
    expect((await fixture.register({})).id).toBe(first.id);
    await expect(fixture.register({ name: "other-job" }, key)).rejects.toMatchObject({
      code: "IDEMPOTENCY_CONFLICT",
    });
    const changed = await fixture.register({ effectPolicy: "protected" });
    expect(changed.id).toBe(first.id);
    expect(changed.revision).toBe(1);
    expect(changed.hash).not.toBe(first.hash);
    await expect(fixture.register({ expectedEnvironmentRevision: 99 })).rejects.toMatchObject({
      code: "REVISION_CONFLICT",
    });
    await expect(
      fixture.register({ trigger: { kind: "cron", cron: "61 * * * *" } }),
    ).rejects.toMatchObject({ code: "INVALID_CRON" });
    await expect(
      fixture.infrastructure.jobs.registerDefinition(
        { ...fixture.freshOwner(), authenticatedAt: "2020-01-01T00:00:00.000Z" },
        {
          projectId: fixture.project.id,
          environmentId: fixture.development.id,
          expectedEnvironmentRevision: fixture.development.revision,
          name: "stale-session",
          handler: "fixture.work",
          trigger: { kind: "manual" },
          effectPolicy: "read_only",
          limits: { maxConcurrent: 1, maxAttempts: 1, timeoutSeconds: 5, retentionDays: 7 },
        },
        randomUUID(),
      ),
    ).rejects.toMatchObject({ code: "STEP_UP_REQUIRED" });
  });
  it("pauses and resumes under revision control without backfilling", async () => {
    const definition = await fixture.register({ trigger: { kind: "cron", cron: "*/5 * * * *" } });
    expect(definition.nextFireAt).toBe("2026-11-11T12:05:00.000Z");
    const paused = await fixture.infrastructure.jobs.pause(
      fixture.freshOwner(),
      definition.id,
      definition.revision,
      randomUUID(),
    );
    expect(paused).toMatchObject({ paused: true, nextFireAt: null, revision: 1 });
    await expect(
      fixture.infrastructure.jobs.pause(fixture.freshOwner(), definition.id, 0, randomUUID()),
    ).rejects.toMatchObject({ code: "REVISION_CONFLICT" });
    await expect(
      fixture.trigger(definition.id, paused.revision, "while-paused-1"),
    ).rejects.toMatchObject({ code: "DEFINITION_PAUSED" });
    fixture.clock.advance(3_600_000);
    const resumed = await fixture.infrastructure.jobs.resume(
      fixture.freshOwner(),
      definition.id,
      paused.revision,
      randomUUID(),
    );
    expect(resumed.nextFireAt).toBe("2026-11-11T13:05:00.000Z");
    await fixture.work();
    expect((await fixture.infrastructure.jobs.overview(fixture.freshOwner())).runs).toHaveLength(0);
  });
  it("runs a cron fire exactly once under duplicate scheduler ticks", async () => {
    const definition = await fixture.register({ trigger: { kind: "cron", cron: "*/5 * * * *" } });
    fixture.clock.advance(5 * 60_000);
    const [a, b] = await Promise.all([fixture.jobs().tick(), fixture.jobs().tick()]);
    expect(a.scheduled + b.scheduled).toBe(1);
    await fixture.work();
    await fixture.jobs().tick();
    const overview = await fixture.jobs().overview(fixture.freshOwner());
    expect(overview.runs).toHaveLength(1);
    expect(overview.runs[0]).toMatchObject({ state: "succeeded", trigger: "cron", attempt: 1 });
    expect(overview.definitions[0]?.nextFireAt).toBe("2026-11-11T12:10:00.000Z");
    expect(fixture.handler.calls).toHaveLength(1);
    expect(overview.runs[0]?.definitionId).toBe(definition.id);
  });
  it("collapses dedupe-key collisions and rejects a colliding key with a different payload", async () => {
    const definition = await fixture.register();
    const first = await fixture.trigger(definition.id, 0, "manual-key-0001");
    const again = await fixture.trigger(definition.id, 0, "manual-key-0001");
    expect(again.id).toBe(first.id);
    await expect(
      fixture.trigger(definition.id, 0, "manual-key-0001", randomUUID()),
    ).rejects.toMatchObject({ code: "IDEMPOTENCY_CONFLICT" });
    await expect(fixture.trigger(definition.id, 7, "manual-key-0002")).rejects.toMatchObject({
      code: "REVISION_CONFLICT",
    });
    await fixture.work();
    expect(fixture.handler.calls).toHaveLength(1);
    expect((await fixture.state(first.id)).state).toBe("succeeded");
  });
  it("consumes duplicate events once and ignores non-matching or paused definitions", async () => {
    const event = await fixture.register({
      name: "on-signup",
      trigger: { kind: "event", eventType: "user.signup" },
    });
    await fixture.register({
      name: "on-other",
      trigger: { kind: "event", eventType: "user.other" },
    });
    const owner = fixture.freshOwner();
    const input = {
      projectId: fixture.project.id,
      environmentId: fixture.development.id,
      eventType: "user.signup",
      eventId: "evt-0000000001",
    };
    const one = await fixture.jobs().ingestEvent(owner, input);
    const two = await fixture.jobs().ingestEvent(owner, input);
    expect(one).toHaveLength(1);
    expect(two[0]?.id).toBe(one[0]?.id);
    await fixture.work();
    expect(fixture.handler.calls).toHaveLength(1);
    await fixture.infrastructure.jobs.pause(owner, event.id, event.revision, randomUUID());
    expect(
      await fixture.jobs().ingestEvent(owner, { ...input, eventId: "evt-0000000002" }),
    ).toEqual([]);
  });
  it("bounds concurrency per definition and drains the queue as slots free", async () => {
    const definition = await fixture.register({
      limits: { maxConcurrent: 1, maxAttempts: 1, timeoutSeconds: 30, retentionDays: 7 },
    });
    const first = await fixture.trigger(definition.id, 0, "concurrent-0001");
    const second = await fixture.trigger(definition.id, 0, "concurrent-0002");
    await fixture.jobs().tick();
    const dispatched = (await fixture.jobs().overview(fixture.freshOwner())).runs.filter(
      (run) => run.runId,
    );
    expect(dispatched).toHaveLength(1);
    await fixture.work();
    await fixture.work();
    expect((await fixture.state(first.id)).state).toBe("succeeded");
    expect((await fixture.state(second.id)).state).toBe("succeeded");
  });
  it("reports an unconfigured engine honestly and refuses to run", async () => {
    const bare = await jobsFixture({ configured: false });
    try {
      const definition = await bare.register();
      const overview = await bare.jobs().overview(bare.freshOwner());
      expect(overview.engine).toMatchObject({ state: "unconfigured", heldEnvironmentIds: [] });
      expect(overview.engine.reason).toMatch(/unconfigured/);
      expect(overview.definitions).toHaveLength(1);
      await expect(bare.trigger(definition.id, 0, "no-engine-001")).rejects.toMatchObject({
        code: "CAPABILITY_UNAVAILABLE",
        status: 503,
      });
      expect(await bare.jobs().tick()).toMatchObject({ scheduled: 0, dispatched: 0, settled: 0 });
      const live = await jobsFixture();
      try {
        expect((await live.jobs().overview(live.freshOwner())).engine.state).toBe("local_fixture");
      } finally {
        await live.store.close();
      }
    } finally {
      await bare.store.close();
    }
  });
});
